from typing import List

def compare_versions(a: str, b: str) -> int:
    def _parse_version(version: str) -> List:
        # Regular expression to match the version format
        version_regex = r'^(?P<major>\d+)\.(?P<minor>\d+)\.(?P<patch>\d+)(?:-(?P<pre_release>[0-9A-Za-z-\.]*))?(?:\+(?P<build_metadata>[0-9A-Za-z-\.]*))?$'
        match = re.match(version_regex, version)
        if not match:
            raise ValueError(f"Invalid version format: {version}")

        major = int(match.group('major'))
        minor = int(match.group('minor'))
        patch = int(match.group('patch'))
        pre_release = match.group('pre_release')

        if pre_release:
            pre_release_parts = pre_release.split('.')
            for part in pre_release_parts:
                if part.isdigit() and part[0] == '0' and len(part) > 1:
                    raise ValueError(f"Invalid pre-release version part: {part}")
        else:
            pre_release_parts = []

        return [major, minor, patch, pre_release_parts]

    version_a = _parse_version(a)
    version_b = _parse_version(b)

    # Compare major, minor, and patch
    for i in range(3):
        if version_a[i] < version_b[i]:
            return -1
        elif version_a[i] > version_b[i]:
            return 1

    # Compare pre-release versions
    pre_a = version_a[3]
    pre_b = version_b[3]

    if pre_a and not pre_b:
        return -1
    if not pre_a and pre_b:
        return 1

    # Compare pre-release identifiers
    for part_a, part_b in zip(pre_a, pre_b):
        if part_a.isdigit() and part_b.isdigit():
            if int(part_a) < int(part_b):
                return -1
            elif int(part_a) > int(part_b):
                return 1
        elif part_a.isdigit():
            return -1
        elif part_b.isdigit():
            return 1
        else:
            if part_a < part_b:
                return -1
            elif part_a > part_b:
                return 1

    # If all shared identifiers are equal, the longer list wins
    if len(pre_a) < len(pre_b):
        return -1
    elif len(pre_a) > len(pre_b):
        return 1

    return 0

def parse_csv_line(line: str) -> list[str]:
    fields = []
    current_field = []
    in_quotes = False
    i = 0
    length = len(line)

    while i < length:
        char = line[i]

        if in_quotes:
            if char == '"':
                # Check for a doubled quote
                if i + 1 < length and line[i + 1] == '"':
                    current_field.append('"')
                    i += 1  # Skip the next quote
                else:
                    in_quotes = False  # End of quoted field
            else:
                current_field.append(char)
        else:
            if char == '"':
                in_quotes = True
            elif char == ',':
                fields.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(char)

        i += 1

    if in_quotes:
        raise ValueError("Unterminated quoted field")

    # Add the last field if it exists
    fields.append(''.join(current_field))

    # Validate the last character
    if length > 0 and line[-1] != ',' and line[-1] != '"':
        raise ValueError("Invalid CSV line format")

    return fields

