import re

def evaluate(expr: str) -> float:
    tokens = _tokenize(expr)
    rpn = _to_rpn(tokens)
    return _evaluate_rpn(rpn)

def _tokenize(expr: str) -> list:
    expr = expr.replace(' ', '')
    token_pattern = r'(\d+(\.\d+)?|[+\-*/()**])'
    tokens = re.findall(token_pattern, expr)
    if not tokens or ''.join(tokens).replace('.', '', 1).isdigit() is False:
        raise ValueError("Malformed expression")
    return [token for token, _ in tokens]

def _to_rpn(tokens: list) -> list:
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
    output = []
    operators = []

    for token in tokens:
        if _is_number(token):
            output.append(token)
        elif token in precedence:
            while (operators and operators[-1] != '(' and
                   (precedence[operators[-1]] > precedence[token] or
                    (precedence[operators[-1]] == precedence[token] and token != '**'))):
                output.append(operators.pop())
            operators.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            if not operators:
                raise ValueError("Unbalanced parentheses")
            operators.pop()  # pop the '('
        else:
            raise ValueError("Malformed expression")

    while operators:
        top = operators.pop()
        if top in '()':
            raise ValueError("Unbalanced parentheses")
        output.append(top)

    return output

def _evaluate_rpn(rpn: list) -> float:
    stack = []

    for token in rpn:
        if _is_number(token):
            stack.append(float(token))
        else:
            b = stack.pop()
            a = stack.pop() if stack else 0  # For unary operators
            result = _apply_operator(a, b, token)
            stack.append(result)

    if len(stack) != 1:
        raise ValueError("Malformed expression")

    return stack[0]

def _is_number(token: str) -> bool:
    return re.match(r'^\d+(\.\d+)?$', token) is not None

def _apply_operator(a: float, b: float, operator: str) -> float:
    if operator == '+':
        return a + b
    elif operator == '-':
        return a - b
    elif operator == '*':
        return a * b
    elif operator == '/':
        if b == 0:
            raise ZeroDivisionError("Division by zero")
        return a / b
    elif operator == '**':
        return a ** b
    else:
        raise ValueError("Unknown operator")

import re

def evaluate(expr: str) -> float:
    tokens = _tokenize(expr)
    return _parse_expression(tokens)

def _tokenize(expr: str) -> list:
    expr = re.sub(r'\s+', '', expr)  # Remove whitespace
    token_pattern = r'(\d+(\.\d+)?)|[+\-*/()**]'
    tokens = re.findall(token_pattern, expr)
    tokens = [t[0] for t in tokens]  # Extract the full match from the tuples
    if ''.join(tokens) != expr:  # Check for any invalid characters
        raise ValueError("Malformed expression")
    return tokens

def _parse_expression(tokens: list) -> float:
    def _parse_primary(index: int) -> (float, int):
        token = tokens[index]
        if token.isdigit() or re.match(r'\d+\.\d+', token):
            return float(token), index + 1
        elif token == '(':
            value, next_index = _parse_expression(tokens[index + 1:])
            if tokens[next_index] != ')':
                raise ValueError("Unbalanced parentheses")
            return value, next_index + 1
        elif token in ('+', '-'):
            value, next_index = _parse_primary(index + 1)
            return -value if token == '-' else value, next_index
        raise ValueError("Invalid token")

    def _parse_exponent(index: int) -> (float, int):
        value, index = _parse_primary(index)
        while index < len(tokens) and tokens[index] == '**':
            index += 1
            right_value, index = _parse_exponent(index)
            value **= right_value
        return value, index

    def _parse_term(index: int) -> (float, int):
        value, index = _parse_exponent(index)
        while index < len(tokens) and tokens[index] in ('*', '/'):
            op = tokens[index]
            index += 1
            right_value, index = _parse_exponent(index)
            if op == '*':
                value *= right_value
            elif op == '/':
                if right_value == 0:
                    raise ZeroDivisionError("Division by zero")
                value /= right_value
        return value, index

    def _parse_expression(index: int) -> (float, int):
        value, index = _parse_term(index)
        while index < len(tokens) and tokens[index] in ('+', '-'):
            op = tokens[index]
            index += 1
            right_value, index = _parse_term(index)
            if op == '+':
                value += right_value
            elif op == '-':
                value -= right_value
        return value, index

    result, next_index = _parse_expression(0)
    if next_index != len(tokens):
        raise ValueError("Dangling operator or invalid input")
    return result

