def _tokenize(expr: str) -> list:
    expr = expr.replace(' ', '')
    token_pattern = r'(\d+(\.\d+)?|[+\-*/()**])'
    tokens = re.findall(token_pattern, expr)
    if not tokens or ''.join(token[0] for token in tokens).replace('.', '', 1).isdigit() is False:
        raise ValueError("Malformed expression")
    return [token[0] for token in tokens]

def _parse_expression(tokens: list) -> float:
    def _parse_primary(index: int) -> (float, int):
        token = tokens[index]
        if token == '(':
            value, index = _parse_expression(index + 1)
            if tokens[index] != ')':
                raise ValueError("Unbalanced parentheses")
            return value, index + 1
        elif token in ('+', '-'):
            value, index = _parse_primary(index + 1)
            return -value if token == '-' else value, index
        else:
            try:
                return float(token), index + 1
            except ValueError:
                raise ValueError("Malformed expression")

    def _parse_power(index: int) -> (float, int):
        value, index = _parse_primary(index)
        while index < len(tokens) and tokens[index] == '**':
            index += 1
            right, index = _parse_power(index)
            value **= right
        return value, index

    def _parse_term(index: int) -> (float, int):
        value, index = _parse_power(index)
        while index < len(tokens) and tokens[index] in ('*', '/'):
            op = tokens[index]
            index += 1
            right, index = _parse_power(index)
            if op == '*':
                value *= right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                value /= right
        return value, index

    def _parse_expression(index: int) -> (float, int):
        value, index = _parse_term(index)
        while index < len(tokens) and tokens[index] in ('+', '-'):
            op = tokens[index]
            index += 1
            right, index = _parse_term(index)
            if op == '+':
                value += right
            elif op == '-':
                value -= right
        return value, index

    result, index = _parse_expression(0)
    if index != len(tokens):
        raise ValueError("Dangling operator or malformed expression")
    return result

def normalize_path(path: str) -> str:
    if not path or path[0] != '/':
        raise ValueError("Path must be an absolute Unix path starting with '/'")

    components = path.split('/')
    stack = []

    for component in components:
        if component == '' or component == '.':
            continue
        elif component == '..':
            if stack:
                stack.pop()
        else:
            stack.append(component)

    normalized_path = '/' + '/'.join(stack)
    return normalized_path if normalized_path else '/'

