def _recurse(current, result, path=''):
    if isinstance(current, dict):
        if not current:  # Handle empty dict
            result[path] = {}
        for k, v in current.items():
            new_path = f"{path}.{k}" if path else k
            _recurse(v, result, new_path)
    elif isinstance(current, list):
        if not current:  # Handle empty list
            result[path] = []
        for i, v in enumerate(current):
            new_path = f"{path}.{i}" if path else str(i)
            _recurse(v, result, new_path)
    else:
        result[path] = current

    # Remove the empty dict entry if the path is empty
    if path == '' and isinstance(current, dict) and not current:
        del result[path]

