import re
from typing import List

def compare_versions(a: str, b: str) -> int:
    def parse_version(version: str) -> tuple:
        # Regular expression to match the semantic versioning format
        version_regex = r'^(\d+)\.(\d+)\.(\d+)(?:-([\da-zA-Z-]+(?:\.[\da-zA-Z-]+)*))?(?:\+.*)?$'
        match = re.match(version_regex, version)
        if not match:
            raise ValueError(f"Invalid version string: {version}")

        major, minor, patch, prerelease = match.groups()
        major, minor, patch = int(major), int(minor), int(patch)

        # Split pre-release identifiers if they exist, else empty list
        prerelease_identifiers = prerelease.split('.') if prerelease else []

        # Ensure numeric pre-release identifiers do not have leading zeros
        for identifier in prerelease_identifiers:
            if identifier.isdigit() and identifier.startswith('0') and identifier != '0':
                raise ValueError(f"Invalid pre-release identifier: {identifier}")

        return major, minor, patch, prerelease_identifiers

    major_a, minor_a, patch_a, prerelease_a = parse_version(a)
    major_b, minor_b, patch_b, prerelease_b = parse_version(b)

    # Compare major, minor, and patch versions
    if (major_a, minor_a, patch_a) < (major_b, minor_b, patch_b):
        return -1
    elif (major_a, minor_a, patch_a) > (major_b, minor_b, patch_b):
        return 1

    # Compare pre-release versions
    if prerelease_a and not prerelease_b:
        return -1
    if not prerelease_a and prerelease_b:
        return 1

    # Compare pre-release identifiers lexicographically
    min_length = min(len(prerelease_a), len(prerelease_b))
    for i in range(min_length):
        id_a, id_b = prerelease_a[i], prerelease_b[i]
        if id_a.isdigit() and id_b.isdigit():
            num_a, num_b = int(id_a), int(id_b)
            if num_a < num_b:
                return -1
            elif num_a > num_b:
                return 1
        elif id_a.isdigit():
            return -1  # numeric < alphanumeric
        elif id_b.isdigit():
            return 1  # alphanumeric > numeric
        else:
            if id_a < id_b:
                return -1
            elif id_a > id_b:
                return 1

    # If all shared identifiers are equal, the longer list has higher precedence
    if len(prerelease_a) < len(prerelease_b):
        return -1
    elif len(prerelease_a) > len(prerelease_b):
        return 1

    return 0

