        prerelease_identifiers = prerelease.split('.') if prerelease else []

        # Ensure numeric pre-release identifiers do not have leading zeros
        for identifier in prerelease_identifiers:
            if identifier.isdigit() and identifier.startswith('0') and identifier != '0':
                raise ValueError(f"Invalid pre-release identifier: {identifier}")

        return major, minor, patch, prerelease_identifiers

