def is_valid_isbn(s: str) -> bool:
    cleaned = ''.join(c for c in s if c.isalnum())  # Remove spaces and hyphens
    if len(cleaned) == 10:
        return _is_valid_isbn10(cleaned)
    elif len(cleaned) == 13:
        return _is_valid_isbn13(cleaned)
    return False

def _is_valid_isbn10(isbn: str) -> bool:
    if len(isbn) != 10 or not all(c.isdigit() or c in 'Xx' for c in isbn):
        return False

    total = 0
    for i in range(10):
        if i == 9 and (isbn[i] == 'X' or isbn[i] == 'x'):
            total += 10
        elif isbn[i].isdigit():
            total += (10 - i) * int(isbn[i])
        else:
            return False

    return total % 11 == 0

def _is_valid_isbn13(isbn: str) -> bool:
    if len(isbn) != 13:
        return False

    total = 0
    for i in range(13):
        if isbn[i].isdigit():
            total += int(isbn[i]) * (1 if i % 2 == 0 else 3)
        else:
            return False

    return total % 10 == 0

