def flatten(obj: dict) -> dict:
    result = {}

    def _recurse(current, path):
        if isinstance(current, dict):
            if not current:  # Empty dict
                result['.'.join(path)] = {}
            else:
                for key, value in current.items():
                    _recurse(value, path + [key])
        elif isinstance(current, list):
            if not current:  # Empty list
                result['.'.join(path)] = []
            else:
                for index, value in enumerate(current):
                    _recurse(value, path + [str(index)])
        else:  # Leaf value (scalar)
            result['.'.join(path)] = current

    _recurse(obj, [])
    return result

