def wrap(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("Width must be at least 1")

    if not text.strip():
        return []

    words = text.split()
    lines = []
    current_line = []

    for word in words:
        if len(word) > width:
            if current_line:
                lines.append(' '.join(current_line))
                current_line = []
            # Split the long word into chunks of width
            for i in range(0, len(word), width):
                lines.append(word[i:i + width])
        else:
            if sum(len(w) for w in current_line) + len(current_line) + len(word) > width:
                lines.append(' '.join(current_line))
                current_line = [word]
            else:
                current_line.append(word)

    if current_line:
        lines.append(' '.join(current_line))

    return lines

