def to_base(n: int, base: int) -> str:
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36 inclusive.")

    if n == 0:
        return '0'

    negative = n < 0
    n = abs(n)
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []

    while n > 0:
        result.append(digits[n % base])
        n //= base

    if negative:
        result.append('-')

    return ''.join(reversed(result))


def from_base(s: str, base: int) -> int:
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36 inclusive.")

    s = s.lower()
    if s.startswith('-'):
        negative = True
        s = s[1:]
    else:
        negative = False

    if not s or any(c not in "0123456789abcdefghijklmnopqrstuvwxyz"[:base] for c in s):
        raise ValueError("Invalid string for the given base.")

    result = 0
    for char in s:
        result = result * base + "0123456789abcdefghijklmnopqrstuvwxyz".index(char)

    return -result if negative else result

