from typing import Dict, List
import heapq

def topo_order(deps: Dict[str, List[str]]) -> List[str]:
    # Step 1: Create a graph and a count of incoming edges (in-degrees)
    graph = {task: [] for task in deps}
    in_degree = {task: 0 for task in deps}

    for task, prerequisites in deps.items():
        for prereq in prerequisites:
            graph[prereq].append(task)
            in_degree[task] += 1

    # Step 2: Initialize a priority queue with tasks that have no prerequisites
    min_heap = []
    for task in in_degree:
        if in_degree[task] == 0:
            heapq.heappush(min_heap, task)

    # Step 3: Perform topological sorting
    order = []

    while min_heap:
        current_task = heapq.heappop(min_heap)
        order.append(current_task)

        for dependent in graph[current_task]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(min_heap, dependent)

    # Step 4: Check for cycles
    if len(order) != len(deps):
        raise ValueError("Cycle detected in the dependencies")

    return order

