def rle_encode(s: str) -> str:
    if not s:
        return ""

    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            while count > 9:
                result.append('9' + s[i - 1])
                count -= 9
            result.append(str(count) + s[i - 1])
            count = 1
    while count > 9:
        result.append('9' + s[-1])
        count -= 9
    result.append(str(count) + s[-1])

    return ''.join(result)

def rle_decode(code: str) -> str:
    if len(code) % 2 != 0:
        raise ValueError("Invalid code length")

    result = []
    for i in range(0, len(code), 2):
        count_char = code[i]
        char = code[i + 1]

        if count_char not in '123456789':
            raise ValueError("Invalid digit")

        count = int(count_char)
        result.append(char * count)

    return ''.join(result)

