def rle_encode(s: str) -> str:
    if not s:
        return ''

    encoded = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            while count > 9:
                encoded.append('9' + s[i - 1])
                count -= 9
            encoded.append(str(count) + s[i - 1])
            count = 1
    while count > 9:
        encoded.append('9' + s[-1])
        count -= 9
    encoded.append(str(count) + s[-1])

    return ''.join(encoded)

def rle_decode(code: str) -> str:
    if len(code) % 2 != 0:
        raise ValueError("Invalid encoded string length.")

    decoded = []
    for i in range(0, len(code), 2):
        count_char = code[i]
        char = code[i + 1]
        if not count_char.isdigit() or not (1 <= int(count_char) <= 9):
            raise ValueError("Invalid count character.")
        decoded.append(char * int(count_char))

    return ''.join(decoded)

